def product_array(numbers):
    n = len(numbers)
    if n < 2:
        raise ValueError("Array must contain at least two elements.")
    left_products = [1] * n
    right_products = [1] * n
    result = [1] * n

    for i in range(1, n):
        left_products[i] = left_products[i - 1] * numbers[i - 1]

    for i in range(n - 2, -1, -1):
        right_products[i] = right_products[i + 1] * numbers[i + 1]

    for i in range(n):
        result[i] = left_products[i] * right_products[i]

    return result

class Solution:
    def buddyStrings(self, A: str, B: str) -> bool:
        if len(A) != len(B):
            return False
        if A == B:
            return len(set(A)) < len(A)
        pairs = []
        for a, b in zip(A, B):
            if a != b:
                pairs.append((a, b))
            if len(pairs) > 2:
                return False
        return len(pairs) == 2 and pairs[0] == pairs[1][::-1]

def uniq(seq):
    if not seq:
        return []
    result = [seq[0]]
    for item in seq[1:]:
        if item != result[-1]:
            result.append(item)
    return result

class Solution:
    def validPalindrome(self, s: str) -> bool:
        left, right = 0, len(s) - 1
        while left < right:
            if s[left] != s[right]:
                skip_left = s[left:right]
                skip_right = s[left + 1:right + 1]
                return skip_left == skip_left[::-1] or skip_right == skip_right[::-1]
            left += 1
            right -= 1
        return True

