class Solution:
    def binaryGap(self, n: int) -> int:
        max_gap = 0
        current_gap = 0
        found_one = False
        while n > 0:
            if n % 2 == 1:
                if found_one:
                    max_gap = max(max_gap, current_gap)
                current_gap = 1
                found_one = True
            elif found_one:
                current_gap += 1
            n //= 2
        return max_gap

import math

def peaceful_yard(yard, min_distance):
    cats = []
    for i, row in enumerate(yard):
        for j, cell in enumerate(row):
            if cell in 'LMR':
                cats.append((i, j))
    if len(cats) <= 1:
        return True
    for i in range(len(cats)):
        for j in range(i + 1, len(cats)):
            dx = cats[i][0] - cats[j][0]
            dy = cats[i][1] - cats[j][1]
            dist = math.sqrt(dx ** 2 + dy ** 2)
            if dist < min_distance:
                return False
    return True

