def jumping(arr, n):
    i = 0
    while i < len(arr):
        temp = arr[i]
        arr[i] += 1 if temp < n else -1
        i += temp
    return sum(x == n for x in arr)

class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digit = 1
        while True:
            start = 10 ** (digit - 1)
            end = start * 10 - 1
            total_digits = (end - start + 1) * digit
            if n <= total_digits:
                break
            n -= total_digits
            digit += 1
        num = start + (n - 1) // digit
        return int(str(num)[(n - 1) % digit])

class Solution:
    def modifyString(self, s: str) -> str:
        s = list(s)
        for i, c in enumerate(s):
            if c == '?':
                prev = s[i - 1] if i > 0 else ''
                next_ = s[i + 1] if i < len(s) - 1 else ''
                for c in 'abc':
                    if c != prev and c != next_:
                        s[i] = c
                        break
        return ''.join(s)

def chessboard(s):
    n, m = map(int, s.split())
    if n == 0 or m == 0:
        return ''
    result = []
    for i in range(n):
        row = ''
        for j in range(m):
            if (i + j) % 2 == 0:
                row += '*'
            else:
                row += '.'
        result.append(row)
    return '\n'.join(result)

class Solution:
    def licenseKeyFormatting(self, S: str, K: int) -> str:
        S = S.replace('-', '').upper()
        if len(S) % K == 0:
            return '-'.join([S[i:i+K] for i in range(0, len(S), K)])
        else:
            return S[:len(S)%K] + '-' + '-'.join([S[i:i+K] for i in range(len(S)%K, len(S), K)])
